// SPDX-License-Identifier: GPL-3.0-only
// Opt-in check (Batch 10) of the REAL Windows key protection path: Electron safeStorage (DPAPI) +
// the real CacheKeyStore + the real agent's encrypted cache, across separate Electron processes
// (= app restarts). The provider is the TEST-ONLY fixture (generated bytes), so this verifies key
// protection and cache hits for real, but not live Dropbox behavior.
//
//   node vfs/tests/key-protection-check.mjs agent desktop
import { spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { createRequire } from 'node:module';
import { BOX, checker, expected, sha } from './lib/fixture-harness.mjs';

const agentDir = resolve(process.argv[2] ?? 'agent');
const desktopDir = resolve(process.argv[3] ?? 'desktop');
const { check, failed } = checker();
const work = mkdtempSync(join(tmpdir(), 'hd-keyprot-'));
// Compile the real CacheKeyStore (desktop/src) with the project's TypeScript, unchanged.
const ts = createRequire(join(desktopDir, 'package.json'))('typescript');
const source = readFileSync(join(desktopDir, 'src/main/storage/cache-key-store.ts'), 'utf8');
const compiled = join(work, 'cache-key-store.cjs');
writeFileSync(compiled, ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText);
const electron = join(desktopDir, 'node_modules', 'electron', 'dist', 'electron.exe');
const userData = join(work, 'userData');
const dataDir = join(work, 'agent-data'); // persistent across "restarts", like the real app
mkdirSync(userData, { recursive: true });
const file = { account: BOX, id: 'id:keyprot', name: 'k.bin', provider: 'DROPBOX', size: 9 * 1024 * 1024, seed: 21, rev: '5a1b2c3d4e5' };
const spec = JSON.stringify({ user: '33333333-4444-4555-8666-777777777777', files: [file], tokens: { google: `g-${randomBytes(16).toString('hex')}`, dropbox: `fixture-dropbox-${randomBytes(16).toString('hex')}` } });
const wantSha = sha(expected(file.seed, 1000, 100000));
// A real Electron app, not Node mode (this variable may be inherited from the calling environment).
const appEnv = Object.fromEntries(Object.entries(process.env).filter(([k]) => k.toUpperCase() !== 'ELECTRON_RUN_AS_NODE'));
const runApp = (mode) => {
  const r = spawnSync(electron, [join(import.meta.dirname, 'lib', 'key-protection-electron.mjs'), mode, userData, compiled, agentDir, dataDir, spec],
    { encoding: 'utf8', timeout: 120_000, windowsHide: true, env: appEnv });
  const line = (r.stdout ?? '').split(/\r?\n/).find((l) => l.startsWith('{'));
  const out = line ? JSON.parse(line) : { error: `no output (${r.status}) ${(r.stderr ?? '').slice(0, 200)}` };
  console.log(`INFO ${mode}: ${JSON.stringify(out)}`);
  return out;
};

const a = runApp('create');
check('real safeStorage available and the store enabled', a.encryptionAvailable === true && a.storeAvailable === true);
check('first start creates a key, wrapped by Electron/DPAPI ("v10"), no plaintext in the key file', a.fresh === true && a.dpapiMarker === 'v10' && a.keyFileHasPlainKey === false);
check('first read is a cache miss with exact bytes, stored encrypted', a.cache === 'miss' && a.readSha === wantSha && a.entriesAfter >= 1);
const b = runApp('recover');
check('restart recovers the SAME key from the DPAPI-wrapped file', b.fresh === false && b.fingerprint === a.fingerprint);
check('...and the encrypted cache answers the read (hit, exact bytes)', b.cache === 'hit' && b.readSha === wantSha && b.entriesAtStart >= 1);
const c = runApp('corrupt');
check('corrupted wrapped key: a new key, old entries purged (never decrypted with a wrong key)', c.fresh === true && c.fingerprint !== a.fingerprint && c.entriesAtStart === 0);
check('...reads keep working (miss, exact bytes)', c.cache === 'miss' && c.readSha === wantSha);
const d = runApp('truncated');
check('truncated key file: same safe outcome', d.fresh === true && d.entriesAtStart === 0 && d.cache === 'miss' && d.readSha === wantSha);
const e = runApp('missing');
check('missing key file: same safe outcome', e.fresh === true && e.entriesAtStart === 0 && e.cache === 'miss' && e.readSha === wantSha);
check('agent logs never mention the key directory', [a, b, c, d, e].every((x) => x.agentLogHasKeyPath === false));

// No plaintext: none of the cached chunk files contains a 4 KiB run of the file's real bytes.
const needle = expected(file.seed, 4096 * 3, 4096);
const files = [];
const walk = (dir) => { for (const n of readdirSync(dir)) { const p = join(dir, n); statSync(p).isDirectory() ? walk(p) : files.push(p); } };
walk(join(dataDir, 'cache'));
const plaintext = files.some((p) => readFileSync(p).includes(needle));
check('no plaintext content in any cache file', files.length > 0 && !plaintext, `${files.length} files scanned`);
rmSync(work, { recursive: true, force: true });
console.log(`${failed() === 0 ? 'OK' : 'FAILED'}: ${failed()} failed -- real Electron safeStorage/DPAPI, fixture provider`);
process.exit(failed() === 0 ? 0 : 1);
